SAMPLES=[paragraph('At equally spaced nodes x₀,…,x₄, the source values are:'),eq(r'x_0=-1,\quad f_0=(-1)^2=1'),eq(r'x_1=-1+\frac34=-\frac14,\quad f_1=\left(-\frac14\right)^2=\frac1{16}=0.0625'),eq(r'x_2=-1+2\frac34=\frac12,\quad f_2=\left(\frac12\right)^2=\frac14=0.25'),eq(r'x_3=-1+3\frac34=\frac54,\quad f_3=\left(\frac54\right)^2=\frac{25}{16}=1.5625'),eq(r'x_4=-1+4\frac34=2,\quad f_4=2^2=4')]
TRAP_EX=[heading('Example 5'),paragraph('Approximate I=∫₋₁²x² dx using n=4 subintervals and compare with the actual value, accurate to five decimal places.'),heading('Solution'),eq(r'\Delta x=\frac{b-a}{n}=\frac{2-(-1)}4=\frac34=0.75'),paragraph('Use the trapezoidal rule:'),eq(r'\int_{-1}^2 x^2\,dx\approx T_4=\frac12[f_0+2f_1+2f_2+2f_3+f_4](0.75)','i')]+SAMPLES+[eq(r'T_4=\frac12[1+2(0.0625)+2(0.25)+2(1.5625)+4](0.75)=3.28125'),paragraph('The exact integral is:'),eq(r'I=\int_{-1}^2x^2\,dx=\left[\frac{x^3}3\right]_{-1}^2=\frac83+\frac13=\frac93=3'),paragraph('The trapezoidal error is actual minus approximation:'),eq(r'E_4=I-T_4=3-3.28125=-0.28125'),paragraph('The negative sign indicates an overestimate. In quadrature notation Q[f(x)]=T₄=3.28125 and E₄[f(x)]=−0.28125 with nodes −1,−1/4,1/2,5/4,2.')]
SIMP_START=[heading('ii. The Simpson’s rule'),paragraph('Instead of trapezoidal strips, use parabolic strips through three consecutive equally spaced grid points. This procedure is Simpson’s rule. Mathematically a parabolic arc is represented by a second-degree polynomial:'),eq(r'p(x)=Ax^2+Bx+C')]
def parabolas():
 vals=[1.6,2.2,2.0,1.8,3.3,3.1,2.8]
 def pt(x,y):return(58+65*x,250-47*y)
 paths=[];labels=[]
 for i in [0,2,4]:
  def poly(t):return vals[i]*(t-1)*(t-2)/2-vals[i+1]*t*(t-2)+vals[i+2]*t*(t-1)/2
  arc=[pt(i+j/30,poly(j/30)) for j in range(61)]
  paths.append(path([pt(i,0)]+arc+[pt(i+2,0),pt(i,0)],fill='#fef3c7' if i!=4 else '#ffedd5',stroke='#ea580c'))
  paths.append(path(arc,stroke='#b91c1c'))
 for i in range(7):
  x,y=pt(i,0);paths.append(path([pt(i,vals[i]),pt(i,0)],dash=True));labels.extend([(x-7,y+21,('a=x₀' if i==0 else 'x₆=b' if i==6 else 'x'+str(i))),(x+4,pt(i,vals[i])[1]-8,'f'+str(i))])
 paths.extend([path([pt(-.3,0),pt(6.7,0)]),path([pt(0,-.2),pt(0,4.6)])]);labels.extend([(494,257,'x'),(50,23,'y'),(449,77,'p(x)')])
 return geometry('Figure 12.6','Figure 12.6 — schematic Simpson quadratic arcs through three consecutive equally spaced samples per panel',paths,labels,size=(535,310))
SIMP_PROOF=[paragraph('Simpson’s rule approximates actual area on [a,b] by a parabolic arc, replacing f with a second-degree p:'),eq(r'\int_a^b f(x)\,dx\approx\int_a^b p(x)\,dx=\int_a^b(Ax^2+Bx+C)\,dx=\frac{b-a}6\left[p(a)+4p\left(\frac{a+b}2\right)+p(b)\right]','i'),paragraph('This requires three consecutive grid points. The second-degree polynomial integral is simplified by a prismoidal rule, valid for polynomial p of degree at most 3. Simpson uses equally spaced points:'),eq(r'x:\ a=x_0,x_1,x_2,\ldots,x_{2n-2},x_{2n-1},x_{2n}=b'),eq(r'f(x):\ f_0,f_1,f_2,\ldots,f_{2n-2},f_{2n-1},f_{2n}'),eq(r'x_{2n}=x_0+2n\Delta x,\quad n=0,1,2,\ldots'),eq(r'b=a+2n\Delta x\quad\Rightarrow\quad\Delta x=\frac{b-a}{2n}','ii'),parabolas(),paragraph('Rearrange the integral over the paired grid intervals:'),eq(r'I=\int_a^b f(x)\,dx=\int_{x_0}^{x_2}f(x)\,dx+\int_{x_2}^{x_4}f(x)\,dx+\ldots+\int_{x_{2n-2}}^{x_{2n}}f(x)\,dx','iii'),paragraph('The parabolic arc on [x₀,x₂] represents approximate area, with a=x₀,b=x₂:'),eq(r'\int_{x_0}^{x_2}f(x)\,dx\approx\int_{x_0}^{x_2}p(x)\,dx=\frac{x_2-x_0}6\left[p(x_0)+4p\left(\frac{x_0+x_2}2\right)+p(x_2)\right]','iv'),paragraph('The source says one-subinterval width is Δx=(b−a)/n. Two consecutive subintervals have x₂−x₀=2Δx and midpoint (x₂+x₀)/2=x₁. Therefore:'),eq(r'\int_{x_0}^{x_2}f(x)\,dx\approx\frac{2\Delta x}6[p(x_0)+4p(x_1)+p(x_2)]=\frac{\Delta x}3[p(x_0)+4p(x_1)+p(x_2)]','v'),paragraph('Because p passes through the three grid points, p(x₀)=f(x₀),p(x₁)=f(x₁),p(x₂)=f(x₂). Substitute these:'),eq(r'\int_{x_0}^{x_2}f(x)\,dx\approx\frac{\Delta x}3[f(x_0)+4f(x_1)+f(x_2)]','vi'),note('Keep a consistent count: with 2n subintervals and n parabolic panels, h=Δx=(b−a)/(2n), n≥1. The later (b−a)/n width line switches conventions and cannot use the same n. With N even subintervals, an equivalent convention is h=(b−a)/N. Simpson is exact for every cubic polynomial as well as quadratics, though the interpolant itself is quadratic. The native schematic shows sample parabolic panels; no numerical source function is specified for Figure 12.6.')]
SIMP_SUM=[paragraph('Sum the areas of all n parabolic strips to give the source approximation:'),eq(r'S_{2n}=\frac{\Delta x}3[f(x_0)+4f(x_1)+2f(x_2)]+\frac{\Delta x}3[f(x_2)+4f(x_3)+f(x_4)]+\ldots+\frac{\Delta x}3[f(x_{2n-2})+4f(x_{2n-1})+f(x_{2n})]'),eq(r'S_{2n}=\frac{\Delta x}3\left[f_0+4(f_1+f_3+\ldots+f_{2n-1})+2(f_2+f_4+\ldots+f_{2n-2})+f_{2n}\right]','viii'),paragraph('In general, for continuous f on [a,b], Simpson’s rule is:'),eq(r'I=\int_a^b f(x)\,dx\approx S_{2n}=\frac{\Delta x}3\left[f_0+4(f_1+f_3+\ldots+f_{2n-1})+2(f_2+f_4+\ldots+f_{2n-2})+f_{2n}\right]'),eq(r'x_{2n}=x_0+2n\Delta x\quad\Rightarrow\quad\Delta x=\frac{b-a}{2n}'),paragraph('The source says larger n gives a better approximation.'),note('In the first displayed panel sum the source wrongly uses 2f(x₂) within the first panel; that endpoint should have coefficient 1 there. The composite formula that follows has the correct total coefficient 2 at shared even-index nodes. Refinement converges under suitable regularity; it does not guarantee a monotonic improvement at every increase of n.')]
EX6_START=[heading('Example 6'),paragraph('Approximate I=∫₋₁²x² dx for n=2 subintervals and compare with the actual value, accurate to five decimals.'),heading('Solution'),eq(r'\Delta x=\frac{b-a}{2n}=\frac{2-(-1)}4=\frac34=0.75'),eq(r'\int_{-1}^2x^2\,dx\approx S_4=\frac{0.75}3[f_0+4(f_1+f_3)+2f_2+f_4]','i')]+SAMPLES+[paragraph('Use these values in equation (i); the source line at the foot of the page is:'),eq(r'\int_{-1}^2x^2\,dx\approx S_4=\frac{0.75}4[f_0+4(f_1+f_3)+2f_2+f_4]'),note('The source n=2 here means two parabolic panels/four subintervals, as its five sample nodes demonstrate. The final denominator 4 is a typo: Simpson’s coefficient is h/3, and the next page returns to 0.75/3. The full numerical conclusion continues on 322.')]
PAGES=[page('164_page_1.jpg',319,TRAP_EX+SIMP_START),page('164_page_2.jpg',320,SIMP_PROOF),page('165_page_1.jpg',321,SIMP_SUM+EX6_START)]
